#!name=游民星空
#!author=queitstart pro
#!date=2026-11-21
#!format=sgmodule

[URL Rewrite]
request if ${url} ~= /^http:\/\/.+\.gamersky\.com\/.+\/adSystem\/ad\/.+/i then reject_dict(200)
request if ${url} ~= /https:\/\/.+\.gamersky.com\/v1\/statisticAd/i then reject_dict(200)
response if ${url} ~= /http:\/\/.+\.gamersky.com\/.+\/lists\/getListElements/i then response.json.jq(".listElements |= map(select(has(\"adCategory\") | not))")

[Rule]
DOMAIN-SUFFIX, ja.gamersky.com,REJECT
DOMAIN-SUFFIX, ja1.gamersky.com,REJECT

[MITM]
hostname = %APPEND% *.gamersky.com
